<?php
require_once '../../config/database.php';require_once '../../config/helpers.php';require_role('admin');$q=trim($_GET['q']??'');$like='%'.$q.'%';$stmt=mysqli_prepare($conn,'SELECT s.id,s.subject_code,s.subject_name,s.units,COUNT(e.id) AS enrollment_count FROM subjects s LEFT JOIN enrollments e ON e.subject_id=s.id WHERE s.subject_code LIKE ? OR s.subject_name LIKE ? GROUP BY s.id ORDER BY s.id DESC');mysqli_stmt_bind_param($stmt,'ss',$like,$like);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);
?>
