><td class="text-end table-actions"><a class="btn btn-light btn-sm" href="edit.php?id=<?=(int)$s['id']?>">Edit</a><form class="d-inline" method="post" action="delete.php" onsubmit="return confirm('Delete this subject and its enrollment records?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$s['id']?>"><button class="btn btn-outline-danger btn-sm">Delete</button></form></td></tr><?php endwhile;else:?><tr><td colspan="5"><div class="empty-state"><strong>No subjects found</strong>Add a subject or adjust your search.</div></td></tr><?php endif;?></tbody></table></div></section></main><script src="../../assets/vendor/bootstrap/js/bootstrap.bundle.min.js"></script></body></html>
